import { expect, test, uniqueName } from "../../fixtures";

const API_TIMEOUT_MS = 60_000;

async function waitForExtraction(
  member: { get: (url: string) => Promise<any> },
  documentId: string,
): Promise<void> {
  const deadline = Date.now() + API_TIMEOUT_MS;
  while (Date.now() < deadline) {
    const response = await member.get(`/api/documents/${documentId}`);
    expect(response.status()).toBe(200);
    const doc = await response.json();
    if (doc.status !== "processing") {
      expect(doc.status).toBe("extracted");
      return;
    }
    await new Promise((resolve) => setTimeout(resolve, 500));
  }
  throw new Error(`document ${documentId} still processing after ${API_TIMEOUT_MS}ms`);
}

test.describe("review vendors", () => {
  test(
    "rejecting an extraction requires a note and returns the vendor to the member",
    { tag: "@REV-06" },
    async ({ apiAs }) => {
      // Arrange: a member creates a vendor with three documents and submits it.
      const member = await apiAs("member");
      const reviewer = await apiAs("reviewer");
      const vendorName = uniqueName("REV-06 Vendor");
      const suffix = `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}`;

      const createResponse = await member.post("/api/vendors", {
        data: {
          name: vendorName,
          category: "software",
          contact_email: `rev06-${suffix}@example.test`,
        },
      });
      expect(createResponse.status()).toBe(201);
      const vendor = await createResponse.json();
      const vendorId: string = vendor.id;

      const kinds = ["w9", "insurance_certificate", "contract"] as const;
      const documentIds: Record<string, string> = {};
      for (const kind of kinds) {
        const uploadResponse = await member.post(`/api/vendors/${vendorId}/documents`, {
          multipart: {
            kind,
            file: {
              name: `${kind}-${suffix}.pdf`,
              mimeType: "application/pdf",
              buffer: Buffer.from(`%PDF-1.4 ${kind} ${suffix}`),
            },
          },
        });
        expect(uploadResponse.status()).toBe(201);
        const doc = await uploadResponse.json();
        documentIds[kind] = doc.id;
      }

      for (const kind of kinds) {
        await waitForExtraction(member, documentIds[kind]);
      }

      const submitResponse = await member.post(`/api/vendors/${vendorId}/submit`);
      expect(submitResponse.status()).toBe(200);

      // The vendor's queue entry holds three pending extractions.
      const queueResponse = await reviewer.get("/api/review-queue");
      expect(queueResponse.status()).toBe(200);
      const queue = (await queueResponse.json()) as Array<{
        vendor_id: string;
        extractions: Array<{ id: string; kind: string; status: string }>;
      }>;
      const item = queue.find((entry) => entry.vendor_id === vendorId);
      expect(item, "vendor appears in review queue").toBeTruthy();
      expect(item!.extractions).toHaveLength(3);
      for (const extraction of item!.extractions) {
        expect(extraction.status).toBe("pending_review");
      }

      const w9Extraction = item!.extractions.find((e) => e.kind === "w9");
      expect(w9Extraction, "W-9 extraction present").toBeTruthy();
      const extractionId = w9Extraction!.id;

      // Act 1: reject the W-9 without a note.
      const noNoteResponse = await reviewer.post(`/api/extractions/${extractionId}/decision`, {
        data: { decision: "reject" },
      });

      // Assert 1
      expect(noNoteResponse.status()).toBe(422);

      // Act 2: reject the W-9 with a note.
      const rejectResponse = await reviewer.post(`/api/extractions/${extractionId}/decision`, {
        data: { decision: "reject", note: "Tax ID does not match" },
      });

      // Assert 2
      expect(rejectResponse.status()).toBe(200);
      const rejected = await rejectResponse.json();
      expect(rejected.status).toBe("rejected");
      expect(rejected.review_note).toBe("Tax ID does not match");

      const vendorResponse = await member.get(`/api/vendors/${vendorId}`);
      expect(vendorResponse.status()).toBe(200);
      expect((await vendorResponse.json()).status).toBe("rejected");

      const auditResponse = await member.get(`/api/vendors/${vendorId}/audit`);
      expect(auditResponse.status()).toBe(200);
      const audit = (await auditResponse.json()) as { items: Array<{ action: string }> };
      expect(audit.items.map((event) => event.action)).toContain("extraction.rejected");
    },
  );
});
